const $=s=>document.querySelector(s);const navs=[['生产运营',[['overview','◈','生产总览'],['orders','▤','生产工单'],['schedule','▦','计划排产'],['routes','⑂','工艺路线'],['trace','⌕','产品追溯']]],['质量与工程',[['quality','◇','质量检验'],['rework','↺','不良与返修'],['sop','▧','SOP 作业指导书'],['devices','▣','设备与测试仪'],['api','⇄','数据接口与日志']]],['资源与协同',[['products','⬡','产品与物料'],['stations','⊞','产线与工位'],['warehouse','▥','仓储与装箱'],['messages','✉','消息中心'],['reports','▥','统计报表']]],['系统管理',[['users','♙','人员与权限'],['audit','≡','操作审计'],['settings','⚙','系统设置'],['login','↪','登录界面']]]];const names=Object.fromEntries(navs.flatMap(g=>g[1].map(n=>[n[0],n[2]])));let page='overview',mode='pc',view='operation',selectedSop=0,scanned=false,passed=false,blocked=false,read=false,stop=false;let orders=[['MO-20261015-001','P20 · 20W 快充充电宝','银灰 / 10000mAh','A01 装配线','2,000','1,486',74,'生产中','今日 18:00'],['MO-20261015-002','P30 · 30W 双向快充','深空黑 / 20000mAh','A02 装配线','1,200','768',64,'生产中','今日 20:00'],['MO-20261016-003','P20 · 20W 快充充电宝','香槟金 / 10000mAh','B01 包装线','3,000','0',0,'待开工','明日 09:00'],['MO-20261014-008','P65 · 65W 移动电源','钛银 / 20000mAh','A03 测试线','800','800',100,'已完成','昨日 17:30']];let msgs=[{title:'质量预警：P20 电芯批次暂缓流转',text:'批次 CELL-261015-B 进入质量复核，请相关工位暂停使用该批次，待质量主管放行。',type:'紧急',time:'16:08',read:false},{title:'SOP 更新：功能测试指导书 V2.4',text:'新增 USB-C 端口复测步骤，请 A01 功能测试工位阅读并确认。',type:'需确认',time:'15:46',read:false},{title:'生产任务：P20 银灰款 2,000 台',text:'今日目标 2,000 台，请班组确认领用物料并按工艺路线执行。',type:'通知',time:'08:30',read:true}];const steps=['电芯绑定','焊接','装配','功能测试','老化','终检','包装'];function badge(t){return `<span class="badge ${/合格|完成|在线|启用|已发布|成功|PASS|正常/.test(t)&&!/不合格/.test(t)?'green':/不良|失败|异常|紧急|FAIL|隔离|拦截/.test(t)?'red':/待|需|离线|维修/.test(t)?'amber':'teal'}">${t}</span>`}function button(t,fn,cls=''){return `<button class="${cls}" onclick="${escapeHtml(fn)}">${t}</button>`}function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.tt);window.tt=setTimeout(()=>$('#toast').style.display='none',3200)}function go(p){page=p;mode='pc';render();window.scrollTo(0,0)}function setMode(m){mode=m;render();window.scrollTo(0,0)}function table(head,rows){return `<div class="tablewrap"><table><thead><tr>${head.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}function panel(title,body,right=''){return `<section class="panel"><div class="panelhead"><h2>${title}</h2>${right}</div>${body}</section>`}function stats(data){return `<div class="stats">${data.map((x,i)=>`<div class="stat"><span class="mini">${['▥','↗','✓','◷'][i]}</span><div class="label">${x[0]}</div><strong>${x[1]}</strong><small>${x[2]}</small></div>`).join('')}</div>`}function heading(title,sub,acts=''){return `<div class="heading"><div><div class="eyebrow">POWER MES / ${mode==='pc'?'WORKSPACE':'SHOP FLOOR'}</div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${acts}</div></div>`}function bars(){return `<div class="chart">${[65,82,72,94,86,77,61,52].map((n,i)=>`<div class="barwrap"><div class="bar soft" style="height:90%"></div><div class="bar" style="height:${n}%"></div><span>${8+i}:00</span></div>`).join('')}</div>`}function route(active=3){return `<div class="route">${steps.map((x,i)=>`${i?'<span class="arrow">›</span>':''}<div class="step ${i===active?'active':''}"><small>工序 ${String(i+1).padStart(2,'0')} ${i<active?'✓':''}</small><b>${x}</b>${badge(i<active?'已完成':i===active?'当前工序':'待加工')}</div>`).join('')}</div>`}function detailRows(arr){return arr.map(x=>`<div class="summaryrow"><span class="sub">${x[0]}</span><b>${x[1]}</b></div>`).join('')}function escapeHtml(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function modal(title,body,footer=''){ $('#modal').innerHTML=`<div class="modalback" onclick="if(event.target===this)closeModal()"><div class="dialog" role="dialog" aria-modal="true" aria-label="${title}"><div class="panelhead"><h2>${title}</h2><button class="close" onclick="closeModal()" aria-label="关闭">×</button></div>${body}<div class="foot">${footer||button('关闭','closeModal()')}</div></div></div>`;$('#modal input')?.focus()}function closeModal(){$('#modal').innerHTML=''}function form(fields){return `<div class="formgrid">${fields.map(([label,val,type])=>`<label class="field">${label}${type==='select'?`<select>${val.split('|').map(x=>`<option>${x}</option>`).join('')}</select>`:`<input value="${val||''}" placeholder="请输入${label}">`}</label>`).join('')}</div>`}function newRecord(kind){modal('新增'+kind,form(kind==='生产工单'?[['工单编号','MO-20261016-005'],['产品型号','P20 · 20W 快充充电宝|P30 · 30W 双向快充','select'],['计划数量','1000'],['生产线','A01 装配线|A02 装配线','select'],['计划开始','2026-10-16 08:00'],['计划完成','2026-10-16 18:00']]:[['名称',''],['编码',''],['所属产线','A01 装配线|A02 装配线','select'],['状态','启用|停用','select']]),button('取消','closeModal()')+button('保存',`saveRecord('${kind}')`,'primary'))}function saveRecord(kind){const inputs=[...document.querySelectorAll('#modal input')].map(x=>x.value.trim());if(inputs.some(x=>!x)){toast('请填写完整信息');return}if(kind==='生产工单')orders.unshift([inputs[0],'P20 · 20W 快充充电宝','银灰 / 10000mAh','A01 装配线',inputs[1],'0',0,'待开工',inputs[3]]);closeModal();render();toast(kind+'已保存（原型模拟）')}function exportCSV(){let rows=[['工单','产品','规格','产线','数量','完成','进度','状态','交期'],...orders];let a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv;charset=utf-8'}));a.download='MES生产工单.csv';a.click();URL.revokeObjectURL(a.href)}function filterTable(){let q=$('#search')?.value.toLowerCase()||'';let status=$('#statusFilter')?.value||'全部状态';document.querySelectorAll('tbody tr').forEach(r=>r.style.display=r.textContent.toLowerCase().includes(q)&&(status==='全部状态'||r.textContent.includes(status))?'':'none')}
function orderTable(){return table(['工单 / 产品','生产线','计划数量','已完成','进度','状态','计划完成','操作'],orders.map((r,i)=>[`<b>${r[0]}</b><small>${r[1]} · ${r[2]}</small>`,r[3],r[4],r[5],`<div style="min-width:85px">${r[6]}%<div class="progress"><i style="width:${r[6]}%"></i></div></div>`,badge(r[7]),r[8],`<button class="link" onclick="orderDetail(${i})">查看工单 →</button>`]))}function orderDetail(i){let r=orders[i];modal('生产工单 · '+r[0],detailRows([['产品',r[1]],['规格',r[2]],['生产线',r[3]],['计划数量',r[4]],['完成数量',r[5]],['状态',badge(r[7])]])+route(3),button('关闭','closeModal()')+button('进入工位','closeModal();setMode("station")','primary'))}
