function ordersPage(){return heading('生产工单','从下单到完工，掌握每一批产品的生产进度',button('导出', 'exportCSV()')+button('＋ 新建工单',"newRecord('生产工单')",'primary'))+stats([['全部工单','24','本月累计'],['生产中','12','执行中的工单'],['待开工','4','物料及产线待确认'],['已完成','8','按期完成率 96%']])+panel('工单列表',`<div class="filters"><input id="search" placeholder="搜索工单、产品或产线" oninput="filterTable()"><select id="statusFilter" onchange="filterTable()"><option>全部状态</option><option>生产中</option><option>待开工</option><option>已完成</option></select>${button('重置',"$('#search').value='';$('#statusFilter').selectedIndex=0;filterTable()")}</div>`+orderTable()+`<div class="pagination"><span>共 ${orders.length} 条工单</span><span>1</span></div>`)}
