function routesPage(){return heading('工艺路线','用受控工艺定义每一道必经工序和放行条件',button('＋ 新建路线',"newRecord('工艺路线')",'primary'))+panel('P20 · 标准生产路线 V1.3',`<div class="notice">强制顺序执行已开启 · 上一工序未合格，禁止下一站过站 · 工位与设备身份绑定</div>${route(3)}${table(['工序','工位类型','放行条件','SOP','规则'],steps.map((x,i)=>[`${i+1}. ${x}`,i===3?'自动测试工位':'扫码工位',i===3?'测试项目齐全 + PASS':'操作完成 + 检验合格',`SOP-P20-0${i+1} / V2.${i===3?4:1}`,badge('强制必经')]))}`,button('编辑规则',"routeRules()"))}function routeRules(){modal('工序放行规则',`<div class="notice">原型中的规则用于展示；正式生产需由后端强制校验。</div>${['禁止跳过上一工序','拒绝重复过站','不良产品进入返修路线','测试结果必须绑定本次任务','SOP 关键步骤必须确认'].map(x=>`<label class="checkrow"><input type="checkbox" checked>${x}</label>`).join('')}`,button('保存规则',"closeModal();toast('规则已保存（原型模拟）')",'primary'))}
function tracePage(){return heading('产品全程追溯','从成品 SN 回溯物料、工序、测试数据与作业版本')+panel('查询产品',`<div class="scanbox"><input id="traceSn" value="PB261015000128" placeholder="扫描或输入产品 SN">${button('查询追溯',"searchTrace()",'primary')}</div>`)+`<div id="traceResult">${traceResult('PB261015000128')}</div>`}function traceResult(sn){return `<div class="grid2">${panel('产品履历 · '+escapeHtml(sn),`<div class="timeline">${steps.slice(0,4).map((x,i)=>`<div class="event"><time>${['09:12:05','09:14:32','09:18:06','09:21:48'][i]}</time><b>${x} ${badge('合格')}</b><p>工位 A01-0${i+1} · ${['李明','王芳','陈涛','张伟'][i]} · SOP V2.${i===3?4:1}</p><p>${i===3?'输出电压 5.08 V / 输出电流 2.96 A / 测试任务 TT-000128':'工序记录已完整保存'}</p></div>`).join('')}<div class="event"><b>老化 ${badge('待加工')}</b><p>上一工序已合格，等待老化工位扫码。</p></div></div>`)}${panel('产品档案',detailRows([['型号','P20 · 20W 快充'],['生产工单','MO-20261015-001'],['电芯批次','CELL-261015-A'],['PCBA 批次','PCB-261010-03'],['当前状态',badge('待老化')],['测试记录','TT-000128 / PASS']])+button('查看原始测试记录',"testDetail()"))}</div>`}function searchTrace(){let s=$('#traceSn').value.trim();if(!s){toast('请输入 SN');return}$('#traceResult').innerHTML=traceResult(s)}
